var n=`0138-badrijani-nigvzit`;var t=`world-0138`;var a=`GE`;var r=`western-asia`;var l=4;var o=50;var g={en:`Badrijani Nigvzit`,ua:`Баклажани з горіхами`};var s={en:`A classic dish from Georgia, featuring eggplant, walnut, garlic, pomegranate arils. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Грузія. Основні складники: баклажан, волоський горіх, часник, зерна граната. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Cut the vegetables evenly and roast at 200°C for about 20 minutes until tender and lightly charred.`,ua:`Наріжте овочі рівномірно та запікайте при 200°C приблизно 20 хвилин до м’якості й легкої підпеченої скоринки.`,t:[`roasting`],m:20,i:[[`eggplant`,760,`g`],[`extra-virgin-olive-oil`,50,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:12,i:[[`walnut`,210,`g`],[`garlic`,4,`clove`],[`ground-coriander`,5,`g`],[`ground-fenugreek`,3,`g`],[`white-vinegar`,22,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:15,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`pomegranate-arils`,95,`g`],[`cilantro`,15,`g`]]}];var u={slug:n,id:t,country:`GE`,region:r,servings:4,minutes:50,title:g,text:s,steps:d};export{a as country,u as default,t as id,o as minutes,r as region,l as servings,n as slug,d as steps,s as text,g as title};